<div class="mb-4"><p class="eyebrow mb-1">Cold-season planning</p><h1 class="mb-1">Winter Sowing Planner</h1><p class="text-muted mb-0">Eligibility comes only from explicit winter-sowing research fields.</p></div>
<nav class="winter-month-nav" aria-label="Winter sowing month"><?php foreach(winter_sowing_month_choices() as $number=>$name):?><a class="winter-month-link <?=$month===$number?'active':''?>" <?=$month===$number?'aria-current="page"':''?> href="<?=e(url('winter-sowing?month='.$number))?>"><span><?=e($name)?></span><small><?=$month===$number?'Selected':'View seeds'?></small></a><?php endforeach?></nav>
<section class="winter-section mb-5"><div class="section-title-row"><div><p class="eyebrow mb-1">Ready to sow</p><h2 class="h4 mb-0"><?=e(winter_sowing_month_choices()[$month])?> Eligible Seeds</h2></div><span class="garden-count"><?=count($eligible)?></span></div><?php if(!$eligible):?><div class="alert alert-info">No seeds are confirmed eligible for this month. Unknown or unresearched seeds are never treated as suitable.</div><?php else:?><div class="row g-3"><?php foreach($eligible as $seed):?><div class="col-md-6 col-xl-4"><article class="card winter-seed-card h-100"><div class="card-body"><h3 class="h5"><?=e($seed['name'])?><?=($seed['variety']??'')!==''?' <span class="garden-variety">— '.e($seed['variety']).'</span>':''?></h3><dl class="winter-facts"><div><dt>Cold stratification</dt><dd><?=e($seed['cold_stratification'])?></dd></div><div><dt>Hardiness</dt><dd><?=e($seed['winter_hardiness'])?></dd></div></dl><?php if(!demo_read_only()):?><a class="btn btn-success btn-sm" href="<?=e(url('garden/create?'.http_build_query(['seed_id'=>$seed['id'],'method'=>'Winter Sown','month'=>$month])))?>">Create Winter Sown Planting</a><?php endif?></div></article></div><?php endforeach?></div><?php endif?></section>
<section class="winter-research-section"><div class="section-title-row align-items-end"><div><p class="eyebrow mb-1">Seed research</p><h2 class="h4 mb-1">Structured Research Fields</h2><p class="text-muted mb-0"><?=count($unresearched)?> seed(s) remain unknown/unresearched. <?=demo_read_only()?'Research is displayed read-only.':'Saving research here does not infer from ordinary planting data.'?></p></div></div><div class="accordion winter-research" id="winter-research"><?php foreach($seeds as $seed):$fieldId='winter-field-'.$seed['id'].'-'?><div class="accordion-item"><h3 class="accordion-header"><button class="accordion-button collapsed" type="button" data-bs-toggle="collapse" data-bs-target="#winter-seed-<?=e($seed['id'])?>"><span class="research-seed"><small><?=e($seed['seed_number'])?></small><?=e($seed['name'])?></span> <span class="research-badge suitability-<?=e(strtolower(str_replace(' ','-',$seed['winter_sowing_suitability'])))?>"><?=e($seed['winter_sowing_suitability'])?></span></button></h3><div id="winter-seed-<?=e($seed['id'])?>" class="accordion-collapse collapse" data-bs-parent="#winter-research"><div class="accordion-body"><?php if(demo_read_only()):?><dl class="row mb-0"><dt class="col-sm-4">Suitability</dt><dd class="col-sm-8"><?=e($seed['winter_sowing_suitability'])?></dd><dt class="col-sm-4">Cold stratification</dt><dd class="col-sm-8"><?=e($seed['cold_stratification'])?></dd><dt class="col-sm-4">Hardiness</dt><dd class="col-sm-8"><?=e($seed['winter_hardiness'])?></dd><dt class="col-sm-4">Eligible months</dt><dd class="col-sm-8"><?=e(plantable_months_label($seed['winter_sowing_months']))?></dd><dt class="col-sm-4">Notes</dt><dd class="col-sm-8"><?=nl2br(e($seed['winter_sowing_notes'] ?: 'Not recorded'))?></dd><dt class="col-sm-4">Source</dt><dd class="col-sm-8"><?=nl2br(e($seed['winter_sowing_citation'] ?: 'Not recorded'))?></dd></dl><?php else:?><form method="post" action="<?=e(url('winter-sowing/'.$seed['id'].'/research'))?>"><?=csrf_field()?><input type="hidden" name="return_month" value="<?=e($month)?>"><div class="row g-4"><div class="col-md-4"><label class="form-label" for="<?=e($fieldId.'suitability')?>">Suitability</label><select id="<?=e($fieldId.'suitability')?>" class="form-select" name="winter_sowing_suitability"><?php foreach(winter_suitabilities() as $choice):?><option <?=($seed['winter_sowing_suitability']??'Unknown')===$choice?'selected':''?>><?=e($choice)?></option><?php endforeach?></select></div><div class="col-md-4"><label class="form-label" for="<?=e($fieldId.'stratification')?>">Cold stratification</label><select id="<?=e($fieldId.'stratification')?>" class="form-select" name="cold_stratification"><?php foreach(winter_stratification_choices() as $choice):?><option <?=($seed['cold_stratification']??'Unknown')===$choice?'selected':''?>><?=e($choice)?></option><?php endforeach?></select></div><div class="col-md-4"><label class="form-label" for="<?=e($fieldId.'hardiness')?>">Hardy / tender</label><select id="<?=e($fieldId.'hardiness')?>" class="form-select" name="winter_hardiness"><?php foreach(winter_hardiness_choices() as $choice):?><option <?=($seed['winter_hardiness']??'Unknown')===$choice?'selected':''?>><?=e($choice)?></option><?php endforeach?></select></div><fieldset class="col-12"><legend class="form-label">Explicit eligible months</legend><div class="winter-month-checks"><?php foreach(winter_sowing_month_choices() as $number=>$name):?><div class="form-check"><input id="winter-<?=$seed['id']?>-<?=$number?>" class="form-check-input" type="checkbox" name="winter_sowing_months[]" value="<?=$number?>" <?=in_array($number,array_map('intval',explode(',',(string)$seed['winter_sowing_months'])),true)?'checked':''?>><label class="form-check-label" for="winter-<?=$seed['id']?>-<?=$number?>"><?=e($name)?></label></div><?php endforeach?></div></fieldset><div class="col-md-6"><label class="form-label" for="<?=e($fieldId.'notes')?>">Winter-sowing notes</label><textarea id="<?=e($fieldId.'notes')?>" class="form-control research-textarea" rows="5" maxlength="10000" name="winter_sowing_notes"><?=e($seed['winter_sowing_notes'])?></textarea></div><div class="col-md-6"><label class="form-label" for="<?=e($fieldId.'citation')?>">Source / research citation text</label><textarea id="<?=e($fieldId.'citation')?>" class="form-control research-textarea" rows="5" maxlength="10000" name="winter_sowing_citation"><?=e($seed['winter_sowing_citation'])?></textarea></div><div class="col-12 research-actions"><button class="btn btn-success">Save Research Fields</button></div></div></form><?php endif?></div></div></div><?php endforeach?></div></section>
